    private void showCampaignDetail(JSONObject c){currentSection=PROMOTIONS;inSubpage=true;headerSection.setText("Promociones");rebuildNav();LinearLayout p=page();p.addView(backLink("Campañas",()->{promoMode="CAMPAÑAS";showSection(PROMOTIONS,true);}));p.addView(V5Ui.kicker(this,c.optString("type","PROMOCIÓN").toUpperCase(Locale.ROOT)));TextView t=V5Ui.title(this,c.optString("name","Promoción"));t.setPadding(0,V5Ui.dp(this,5),0,V5Ui.dp(this,11));p.addView(t);LinearLayout s=V5Ui.darkCard(this);TextView state=V5Ui.text(this,c.optBoolean("active",false)?"● ACTIVA":"● PAUSADA",10,V5Ui.LIME,true);s.addView(state);TextView schedule=V5Ui.text(this,scheduleSummary(c),11.5f,Color.WHITE,false);schedule.setPadding(0,V5Ui.dp(this,8),0,0);s.addView(schedule);JSONObject st=c.optJSONObject("stats");if(st!=null){TextView m=V5Ui.text(this,st.optInt("plays",0)+" jugadas · "+st.optInt("winners",0)+" premios",13,Color.WHITE,true);m.setPadding(0,V5Ui.dp(this,10),0,0);s.addView(m);}p.addView(s);if(c.optBoolean("active",false))p.addView(action("Generar QR real",true,()->issueQr(c)),top(V5Ui.dp(this,10)));p.addView(action("Editar datos",false,()->editCampaignDialog(c)),top(V5Ui.dp(this,7)));p.addView(action(c.optBoolean("active",false)?"Pausar campaña":"Activar campaña",false,()->toggleCampaign(c)),top(V5Ui.dp(this,7)));swapContent(scrollPage(p),true);}
