    private void editCampaignDialog(JSONObject old){boolean isNew=old==null;LinearLayout box=V5Ui.column(this);box.setPadding(V5Ui.dp(this,16),V5Ui.dp(this,4),V5Ui.dp(this,16),V5Ui.dp(this,5));EditText name=dialogField(box,"Nombre",isNew?"":old.optString("name",""));Spinner type=new Spinner(this);String[] types={"Ruleta","Rasca","Premio directo","Código premiado"};ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,types);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);type.setAdapter(a);if(!isNew){for(int i=0;i<types.length;i++)if(types[i].equals(old.optString("type","")))type.setSelection(i);}box.addView(dialogLabel("Tipo"));box.addView(type,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,V5Ui.dp(this,48)));EditText start=dialogField(box,"Fecha inicio · YYYY-MM-DD",isNew?"":old.optString("startDate",""));EditText end=dialogField(box,"Fecha fin · YYYY-MM-DD",isNew?"":old.optString("endDate",""));EditText startTime=dialogField(box,"Hora inicio",isNew?"00:00":old.optString("startTime","00:00"));EditText endTime=dialogField(box,"Hora fin",isNew?"23:59":old.optString("endTime","23:59"));new AlertDialog.Builder(this).setTitle(isNew?"Nueva campaña":"Editar campaña").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->saveCampaign(old,value(name),String.valueOf(type.getSelectedItem()),value(start),value(end),value(startTime),value(endTime))).show();}
    private void saveCampaign(JSONObject old,String name,String type,String start,String end,String startTime,String endTime){if(name.trim().length()<2){toast("Escribe un nombre");return;}if(!core.configured()){alert("Servidor sin configurar","Configura el acceso primero.");return;}JSONObject c=new JSONObject();try{if(old!=null){String[] keys={"id","description","state","activeDays","winProbability","winMessage","loseMessage","ticketTemplate","totalLimit","clientLimit","dailyLimit","allowedTerminals","order"};for(String k:keys)if(old.has(k))c.put(k,old.opt(k));c.put("active",old.optBoolean("active",false));}else{c.put("state","Pausada").put("active",false).put("activeDays","Lun,Mar,Mié,Jue,Vie,Sáb,Dom").put("winProbability",20).put("winMessage","¡Enhorabuena! Te ha tocado {{premio}}.").put("loseMessage","Esta vez no ha habido premio.").put("clientLimit",1).put("dailyLimit",500).put("order",999);}c.put("name",name).put("type",type).put("startDate",start).put("endDate",end).put("startTime",startTime).put("endTime",endTime).put("requiresCode","Código premiado".equals(type));}catch(Exception ignored){}io.execute(()->{try{core.post(core.action("promotionSave").put("campaign",c));refreshPromotions(true);runOnUiThread(()->{toast("Campaña guardada");promoMode="CAMPAÑAS";showSection(PROMOTIONS,true);});}catch(Exception e){runOnUiThread(()->alert("No se pudo guardar",msg(e)));}});}
    private void toggleCampaign(JSONObject c){if(!core.configured()){alert("Servidor sin configurar","Configura el acceso primero.");return;}boolean active=c.optBoolean("active",false);io.execute(()->{try{core.post(core.action("promotionSetState").put("id",c.optString("id","")).put("state",active?"Pausada":"Activa"));refreshPromotions(true);runOnUiThread(()->{toast(active?"Campaña pausada":"Campaña activada");promoMode="CAMPAÑAS";showSection(PROMOTIONS,true);});}catch(Exception e){runOnUiThread(()->alert("No se pudo cambiar el estado",msg(e)));}});}

    private void paintPrizes(LinearLayout p){TextView count=V5Ui.text(this,prizeCount()+" premios",10.5f,V5Ui.MUTED,false);count.setPadding(0,V5Ui.dp(this,12),0,V5Ui.dp(this,7));p.addView(count);p.addView(action("Nuevo premio",true,()->editPrizeDialog(null)));for(int i=0;i<prizes.length();i++){JSONObject prize=prizes.optJSONObject(i);if(prize==null||"P000".equals(prize.optString("id")))continue;LinearLayout c=V5Ui.card(this);c.setBackground(V5Ui.bg(this,V5Ui.SURFACE_ALT,18));LinearLayout top=V5Ui.row(this);top.addView(V5Ui.text(this,prize.optString("name","Premio"),14.5f,V5Ui.INK,true),new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));top.addView(V5Ui.pill(this,prize.optBoolean("active",true)?"Activo":"Pausado",prize.optBoolean("active",true)?V5Ui.LIME_SOFT:Color.rgb(235,236,232),prize.optBoolean("active",true)?V5Ui.GREEN:V5Ui.MUTED));c.addView(top);c.addView(V5Ui.text(this,"Restante: "+remaining(prize)+" · canjeados: "+prize.optInt("redeemed",0),10.5f,V5Ui.MUTED,false));c.setOnClickListener(v->editPrizeDialog(prize));p.addView(c,top(V5Ui.dp(this,7)));}}
    private void editPrizeDialog(JSONObject old){boolean isNew=old==null;LinearLayout box=V5Ui.column(this);box.setPadding(V5Ui.dp(this,16),V5Ui.dp(this,4),V5Ui.dp(this,16),V5Ui.dp(this,5));EditText name=dialogField(box,"Nombre",isNew?"":old.optString("name",""));EditText stock=dialogField(box,"Stock · vacío = ilimitado",isNew?"":String.valueOf(old.opt("stock")));EditText type=dialogField(box,"Tipo",isNew?"Consumición":old.optString("type","Consumición"));EditText conditions=dialogField(box,"Condiciones",isNew?"":old.optString("conditions",""));new AlertDialog.Builder(this).setTitle(isNew?"Nuevo premio":"Editar premio").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->savePrize(old,value(name),value(stock),value(type),value(conditions))).show();}
    private void savePrize(JSONObject old,String name,String stock,String type,String conditions){if(name.isEmpty()){toast("Escribe el nombre");return;}JSONObject p=new JSONObject();try{if(old!=null)p.put("id",old.optString("id","")).put("active",old.optBoolean("active",true)).put("weight",old.optDouble("weight",1)).put("order",old.optInt("order",999)).put("ticketText",old.optString("ticketText","")).put("imageUrl",old.optString("imageUrl","")).put("value",old.optString("value",""));else p.put("id","").put("active",true).put("weight",1).put("order",999).put("ticketText","");p.put("name",name).put("stock",stock.isEmpty()?"":parse(stock,0)).put("type",type).put("conditions",conditions);}catch(Exception ignored){}io.execute(()->{try{core.post(core.action("promotionPrizeSave").put("prize",p));refreshPromotions(true);runOnUiThread(()->{toast("Premio guardado");promoMode="PREMIOS";showSection(PROMOTIONS,true);});}catch(Exception e){runOnUiThread(()->alert("No se pudo guardar",msg(e)));}});}

    private void paintRedeem(LinearLayout p){TextView title=V5Ui.text(this,"Validar y canjear",19,V5Ui.INK,true);title.setPadding(0,V5Ui.dp(this,12),0,V5Ui.dp(this,4));p.addView(title);p.addView(V5Ui.subtitle(this,"Escanea el QR o introduce el código ganador."));p.addView(action("Escanear QR",true,this::scanQr),top(V5Ui.dp(this,10)));redeemInput=input("");redeemInput.setHint("OF-XXXXX-XXXXX");p.addView(redeemInput,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,V5Ui.dp(this,48)));p.addView(action("Validar código",false,()->validateCode(value(redeemInput))),top(V5Ui.dp(this,7)));redeemResult=V5Ui.text(this,"Todavía no hay ningún código validado.",11.5f,V5Ui.MUTED,false);redeemResult.setPadding(V5Ui.dp(this,13),V5Ui.dp(this,12),V5Ui.dp(this,13),V5Ui.dp(this,12));redeemResult.setBackground(V5Ui.bg(this,V5Ui.SURFACE_SOFT,16));p.addView(redeemResult,top(V5Ui.dp(this,9)));redeemConfirm=action("Confirmar canje",true,this::confirmRedeem);redeemConfirm.setVisibility(View.GONE);p.addView(redeemConfirm,top(V5Ui.dp(this,8)));}
    private void showRedeemPage(){currentSection=PROMOTIONS;promoMode="CANJES";showSection(PROMOTIONS,true);}
    private void scanQr(){IntentIntegrator i=new IntentIntegrator(this);i.setDesiredBarcodeFormats(java.util.Collections.singletonList("QR_CODE"));i.setPrompt("Escanea el premio");i.setBeepEnabled(false);i.setOrientationLocked(true);i.initiateScan();}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){IntentResult r=IntentIntegrator.parseActivityResult(requestCode,resultCode,data);if(r!=null){if(r.getContents()!=null){currentSection=PROMOTIONS;promoMode="CANJES";showSection(PROMOTIONS,false);String code=PromoRules.cleanCode(r.getContents());if(redeemInput!=null){redeemInput.setText(code);validateCode(code);}}return;}super.onActivityResult(requestCode,resultCode,data);}
    private void validateCode(String raw){String code=PromoRules.cleanCode(raw);validatedCode="";if(code.isEmpty()){toast("Código vacío");return;}if(!core.configured()){alert("Servidor sin configurar","Configura el acceso primero.");return;}if(redeemResult!=null)redeemResult.setText("Validando…");io.execute(()->{try{JSONObject r=core.post(core.action("promotionValidate").put("code",code));boolean can=r.optBoolean("canRedeem",false);String finalCode=r.optString("code",code);runOnUiThread(()->{validatedCode=can?finalCode:"";if(redeemResult!=null){redeemResult.setText("Premio: "+dash(r.optString("prize",""))+"\nEstado: "+dash(r.optString("state",""))+"\nPromoción: "+dash(r.optString("promotionName",""))+"\nCódigo: "+finalCode+(can?"\n\nLISTO PARA CANJEAR":"\n\nNo se puede canjear"));redeemResult.setTextColor(can?V5Ui.GREEN:V5Ui.ERROR);}if(redeemConfirm!=null)redeemConfirm.setVisibility(can?View.VISIBLE:View.GONE);});}catch(Exception e){runOnUiThread(()->alert("No se pudo validar",msg(e)));}});}
    private void confirmRedeem(){if(validatedCode.isEmpty())return;String code=validatedCode;new AlertDialog.Builder(this).setTitle("Confirmar canje").setMessage("El código quedará inutilizado después del canje.").setNegativeButton("Cancelar",null).setPositiveButton("Canjear",(d,w)->io.execute(()->{try{JSONObject r=core.post(core.action("promotionRedeem").put("code",code));runOnUiThread(()->{validatedCode="";if(redeemResult!=null)redeemResult.setText("CANJEADO\n"+r.optString("prize","Premio")+"\n"+r.optString("code",code));if(redeemConfirm!=null)redeemConfirm.setVisibility(View.GONE);toast("Canje registrado");});}catch(Exception e){runOnUiThread(()->alert("No se pudo canjear",msg(e)));}})).show();}

    private void showQrGenerator(){currentSection=PROMOTIONS;inSubpage=true;headerSection.setText("Promociones · QR");rebuildNav();LinearLayout p=page();p.addView(backLink("Promociones",()->showSection(PROMOTIONS,true)));p.addView(V5Ui.kicker(this,"QR REAL"));TextView t=V5Ui.title(this,"Generar invitación");t.setPadding(0,V5Ui.dp(this,5),0,V5Ui.dp(this,5));p.addView(t);p.addView(V5Ui.subtitle(this,"Cada QR se registra en el servidor y permite una sola jugada."));int n=0;for(int i=0;i<campaigns.length();i++){JSONObject c=campaigns.optJSONObject(i);if(c==null||!c.optBoolean("active",false))continue;n++;LinearLayout card=V5Ui.card(this);card.setBackground(V5Ui.bg(this,V5Ui.SURFACE_ALT,18));card.addView(V5Ui.text(this,c.optString("name","Promoción"),14.5f,V5Ui.INK,true));card.addView(V5Ui.text(this,scheduleSummary(c),10.5f,V5Ui.MUTED,false));card.addView(action("Generar QR",true,()->issueQr(c)),top(V5Ui.dp(this,8)));p.addView(card,top(V5Ui.dp(this,8)));}if(n==0){LinearLayout e=V5Ui.softCard(this);e.addView(V5Ui.text(this,"No hay promociones activas.",12,V5Ui.MUTED,false));p.addView(e,top(V5Ui.dp(this,10)));}swapContent(scrollPage(p),true);}
    private void issueQr(JSONObject c){if(!core.configured()){alert("Servidor sin configurar","Configura el acceso primero.");return;}io.execute(()->{try{JSONObject r=core.post(core.action("promoPublicIssue").put("id",c.optString("id","")).put("expiresHours",48));String url=r.optString("url","").trim(),token=r.optString("token","").trim();if(!url.startsWith("https://")||token.isEmpty())throw new Exception("Invitación no válida");runOnUiThread(()->showIssuedQr(c,url,token));}catch(Exception e){runOnUiThread(()->alert("No se pudo generar el QR",msg(e)));}});}
    private void showIssuedQr(JSONObject c,String url,String token){inSubpage=true;LinearLayout p=page();p.addView(backLink("QR",this::showQrGenerator));p.addView(V5Ui.kicker(this,"INVITACIÓN CREADA"));TextView t=V5Ui.title(this,c.optString("name","Promoción"));t.setPadding(0,V5Ui.dp(this,5),0,V5Ui.dp(this,10));p.addView(t);LinearLayout card=V5Ui.darkCard(this);card.addView(V5Ui.text(this,"QR REAL · 48 H · UN SOLO USO",10,V5Ui.LIME,true));TextView link=V5Ui.text(this,url,11.5f,Color.WHITE,false);link.setPadding(0,V5Ui.dp(this,8),0,0);card.addView(link);card.addView(V5Ui.text(this,"Token: "+token,9.5f,Color.rgb(190,201,191),false));p.addView(card);p.addView(action("Imprimir QR",true,()->printQr(c,url)),top(V5Ui.dp(this,10)));p.addView(action("Copiar enlace",false,()->copy(url)),top(V5Ui.dp(this,7)));swapContent(scrollPage(p),true);}
    private void printQr(JSONObject c,String url){io.execute(()->{try{core.printQrTicket(c.optString("name","Promoción"),"ESCANEA PARA JUGAR\nQR REAL · UN SOLO USO · 48 H",url);runOnUiThread(()->toast("QR enviado a impresora"));}catch(Exception e){runOnUiThread(()->alert("No se pudo imprimir",msg(e)));}});}

