    private View buildStats(){LinearLayout p=page();p.addView(V5Ui.kicker(this,"ESTADÍSTICAS"));TextView t=V5Ui.title(this,"Datos del negocio");t.setPadding(0,V5Ui.dp(this,5),0,V5Ui.dp(this,4));p.addView(t);p.addView(V5Ui.subtitle(this,"Lectura rápida de reservas, promociones y actividad."));p.addView(periodTabs(),top(V5Ui.dp(this,13)));boolean today="Hoy".equals(statsPeriod);JSONArray rs=today?filterReservations(reservations,"HOY"):new JSONArray();int people=0;for(int i=0;i<rs.length();i++){JSONObject r=rs.optJSONObject(i);if(r!=null)people+=r.optInt("people",0);}LinearLayout r1=V5Ui.row(this);r1.addView(metricCard("RESERVAS",today?String.valueOf(rs.length()):"—",statsPeriod,null),weightGap());r1.addView(metricCard("PERSONAS",today?String.valueOf(people):"—",statsPeriod,null),weightGap());p.addView(r1,top(V5Ui.dp(this,10)));LinearLayout r2=V5Ui.row(this);r2.addView(metricCard("PROMOCIONES",today?String.valueOf(activeCampaignCount()):"—",today?"activas":"histórico pendiente",null),weightGap());r2.addView(metricCard("WEB","—","analítica pendiente",null),weightGap());p.addView(r2,top(V5Ui.dp(this,7)));p.addView(sectionLabel("MÓDULOS"));p.addView(V5Ui.linkCard(this,R.drawable.ic_calendar_v5,"Reservas","Personas, zonas y estados",()->showStatsDetail("Reservas")));p.addView(V5Ui.linkCard(this,R.drawable.ic_gift_v5,"Promociones","QR, jugadas, ganadores y canjes",()->showStatsDetail("Promociones")),top(V5Ui.dp(this,7)));p.addView(V5Ui.linkCard(this,R.drawable.ic_chart_v5,"Web","Visitas, acciones y embudos",()->showStatsDetail("Web")),top(V5Ui.dp(this,7)));p.addView(V5Ui.linkCard(this,R.drawable.ic_print_v5,"Impresión","Tickets y actividad del terminal",()->showStatsDetail("Impresión")),top(V5Ui.dp(this,7)));return scrollPage(p);}
