    private void showStatsDetail(String type){currentSection=STATS;inSubpage=true;headerSection.setText("Estadísticas · "+type);rebuildNav();LinearLayout p=page();p.addView(backLink("Estadísticas",()->showSection(STATS,true)));p.addView(V5Ui.kicker(this,type.toUpperCase(Locale.ROOT)));TextView t=V5Ui.title(this,type);t.setPadding(0,V5Ui.dp(this,5),0,V5Ui.dp(this,12));p.addView(t);if("Reservas".equals(type)){JSONArray a=filterReservations(reservations,"HOY");int interior=0,terrace=0,people=0;for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r==null)continue;people+=r.optInt("people",0);if("Terraza".equalsIgnoreCase(r.optString("zone","")))terrace++;else interior++;}p.addView(bigStat("Reservas hoy",String.valueOf(a.length()),"Personas · "+people));p.addView(bigStat("Distribución","Interior "+interior+" · Terraza "+terrace,"Datos disponibles actualmente"),top(V5Ui.dp(this,8)));}else if("Promociones".equals(type)){int plays=0,winners=0;for(int i=0;i<campaigns.length();i++){JSONObject s=campaigns.optJSONObject(i)==null?null:campaigns.optJSONObject(i).optJSONObject("stats");if(s!=null){plays+=s.optInt("plays",0);winners+=s.optInt("winners",0);}}p.addView(bigStat("Campañas activas",String.valueOf(activeCampaignCount()),plays+" jugadas · "+winners+" ganadores"));}else{p.addView(bigStat(type,"—","La recogida de esta analítica se activará en la fase correspondiente."));}swapContent(scrollPage(p),true);}
